const D = { energy:.55, density:.5, scale:1, speed:1, alpha:.62, hue:195, x:.5, y:.5, style:'dendrite', act:'creep', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};

const W=width, Hh=height, u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style, act=P.act||'creep';
const isHoar=st==='hoar', isEtch=st==='etch', isTherm=st==='thermal';
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

// ---- seeded frost sheet, cached (rebuild on size/seed/style/density) ----
const dq=Math.round(clp(P.density,0,1)*8);
const key=W+'x'+Hh+'|'+P.seed+'|'+st+'|'+dq+'|'+md(Math.round(H),360);
if(!S.fg||S.key!==key){
  const bw=Math.max(320,Math.min(1100,Math.round(W))), bh=Math.max(200,Math.round(bw*Hh/W));
  if(!S.fg||S.bw!==bw||S.bh!==bh){ S.fg=createGraphics(bw,bh); S.bw=bw; S.bh=bh; }
  const g=S.fg, uu=Math.min(bw,bh);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noFill();
  let ctr=0; const rnd=()=>fr(++ctr*1.7+3);

  // cold haze hugging the border — breaks up flat fill, gives the band body
  g.noStroke();
  const steps=30, band=uu*0.46;
  for(let i=0;i<steps;i++){
    const f=i/steps, inset=f*band;
    const a=(1-f)*(1-f)*(isEtch?7:isTherm?9:13);
    g.fill(isTherm?md(H+150,360):md(H+6,360), isEtch?4:isTherm?60:22, isEtch?86:isTherm?46:92, a);
    g.rect(inset,inset,bw-inset*2,bh-inset*2);
  }

  // dendrites nucleating on the border and growing inward (hexagonal ice habit)
  const sites=Math.round(lrp(26,96,clp(P.density,0,1)));
  const per=2*(bw+bh);
  const grow=(x,y,ang,len,dep,w)=>{
    if(dep<0||len<uu*0.006) return;
    const segs=isHoar?4:6; let px=x,py=y,a=ang;
    for(let i=0;i<segs;i++){
      a+=(rnd()-0.5)*(isHoar?0.10:0.26);
      const sl=len/segs, nx=px+Math.cos(a)*sl, ny=py+Math.sin(a)*sl;
      const f=i/segs;
      if(isTherm){ g.stroke(md(H+150-dep*46-f*44,360), 74, lrp(52,100,f*0.5+dep*0.2), 76); }
      else if(isEtch){ g.stroke(md(H,360), 5, 88, lrp(70,26,f)); }
      else { g.stroke(md(H+lrp(-6,10,f),360), isHoar?9:18, lrp(88,100,f), lrp(58,88,f)); }
      g.strokeWeight(Math.max(0.4,w*(1-f*0.5)));
      g.line(px,py,nx,ny);
      if(!isEtch&&dep>=1&&i===1){ // soft crystal bloom on the trunk only (few shapes)
        g.drawingContext.shadowBlur=uu*0.012; g.drawingContext.shadowColor='rgba(210,240,255,0.5)';
        g.line(px,py,nx,ny); g.drawingContext.shadowBlur=0;
      }
      if(dep>=1&&i%2===1){
        const sg=rnd()>0.5?1:-1, br=Math.PI/3; // 60° — real ice branching angle
        grow(nx,ny,a+sg*br,len*(isHoar?0.30:0.46),dep-1,w*0.6);
        grow(nx,ny,a-sg*br,len*(isHoar?0.26:0.36),dep-1,w*0.52);
      }
      px=nx; py=ny;
    }
    if(isEtch){ // stipple the branch axis — engraving texture instead of bloom
      g.noStroke(); g.fill(md(H,360),4,92,40);
      for(let k=0;k<5;k++){ const f2=rnd(); g.circle(lrp(x,px,f2)+(rnd()-0.5)*uu*0.01, lrp(y,py,f2)+(rnd()-0.5)*uu*0.01, uu*0.0022); }
      g.noFill();
    }
  };
  for(let i=0;i<sites;i++){
    const d=rnd()*per; let x,y,na;
    if(d<bw){ x=d; y=0; na=Math.PI/2; }
    else if(d<bw+bh){ x=bw; y=d-bw; na=Math.PI; }
    else if(d<2*bw+bh){ x=bw-(d-bw-bh); y=bh; na=-Math.PI/2; }
    else { x=0; y=bh-(d-2*bw-bh); na=0; }
    grow(x,y,na+(rnd()-0.5)*0.9, uu*lrp(0.10,0.30,rnd())*(isHoar?0.7:1), isHoar?1:2, uu*lrp(0.0016,0.0042,rnd()));
  }
  S.key=key;
}

// ---- the growth front: creeps in and back on incommensurate real-time rates ----
let envD=1, envG=1;
if(act==='bloom'){ envD=0.62+0.75*K.intensity; envG=1.25; }
else if(act==='siege'){ envD=1.42; envG=0.8; }
const breathe=0.58*Math.sin(K.t*0.113*P.speed)+0.27*Math.sin(K.t*0.291*P.speed+1.9)+0.15*Math.sin(K.t*0.047*P.speed+0.4);
const en=clp(P.energy,0,1);
const dep0=u*(0.05+0.38*en)*P.scale*envD*(0.80+0.20*breathe+0.10*A.bass);
const px0=P.x*W, py0=P.y*Hh, diag=Math.hypot(W,Hh);
const NS=112, per=2*(W+Hh), pts=[];
for(let i=0;i<NS;i++){
  const s=i/NS, d=s*per; let x,y,nx,ny,ce;
  if(d<W){ x=d; y=0; nx=0; ny=1; ce=Math.min(d,W-d); }
  else if(d<W+Hh){ const q=d-W; x=W; y=q; nx=-1; ny=0; ce=Math.min(q,Hh-q); }
  else if(d<2*W+Hh){ const q=d-W-Hh; x=W-q; y=Hh; nx=0; ny=-1; ce=Math.min(q,W-q); }
  else { const q=d-2*W-Hh; x=0; y=Hh-q; nx=1; ny=0; ce=Math.min(q,Hh-q); }
  // travelling wobble — three incommensurate K.t rates so the line never re-phases
  const ph=fr(i*2.3+11)*6.283;
  const wob=0.52*Math.sin(s*6.283*11+K.t*0.19*P.speed+ph)
           +0.30*Math.sin(s*6.283*23-K.t*0.31*P.speed+ph*0.7)
           +0.18*Math.sin(s*6.283*37+K.t*0.53*P.speed);
  const corner=1+0.95*Math.exp(-ce/(0.15*u));
  const pull=0.58+0.86*clp(1-Math.hypot(x-px0,y-py0)/(0.80*diag),0,1);
  // clamp: the front must never cross the middle, or the ring polygon inverts under evenodd
  const room=(nx===0?Hh:W)*0.47;
  const dep=Math.min(dep0*corner*pull*(0.60+0.44*wob), room);
  pts.push([x+nx*dep, y+ny*dep]);
}

// ---- composite: frost sheet revealed only inside the wobbling front ----
const al=clp(P.alpha,0,1);
drawingContext.save();
drawingContext.beginPath();
drawingContext.rect(0,0,W,Hh);
drawingContext.moveTo(pts[0][0],pts[0][1]);
for(let i=1;i<NS;i++) drawingContext.lineTo(pts[i][0],pts[i][1]);
drawingContext.closePath();
drawingContext.clip('evenodd');
if(isTherm) blendMode(ADD);
tint(0,0,100,al*100); image(S.fg,0,0,W,Hh); noTint();
blendMode(BLEND);

// facet glints — seeded crystal positions that ignite as the front sweeps over them
const ng=Math.round(lrp(18,60,clp(P.density,0,1)));
noStroke();
for(let i=0;i<ng;i++){
  const gx=fr(i*5.1+70)*W, gy=fr(i*5.1+71)*Hh;
  const tw=0.5+0.5*Math.sin(K.t*(1.1+fr(i*5.1+72)*2.6)*P.speed+fr(i*5.1+73)*6.283);
  const sp=(tw*tw)*(0.34+0.66*en)*al*envG*(1+A.treble*0.9+K.pulse*0.3);
  if(sp<0.04) continue;
  const r=u*0.004*P.scale*(0.5+fr(i*5.1+74)*1.3);
  fill(isTherm?md(H+120,360):md(H+4,360), isEtch?3:14, 100, 30+52*sp);
  circle(gx,gy,r*(1.4+2.2*sp));
  stroke(md(H+4,360),8,100,26+40*sp); strokeWeight(Math.max(0.4,r*0.28));
  line(gx-r*2.4*sp,gy,gx+r*2.4*sp,gy); line(gx,gy-r*2.4*sp,gx,gy+r*2.4*sp);
  noStroke();
}
drawingContext.restore();
blendMode(BLEND); drawingContext.shadowBlur=0;
